import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

public class InvoiceDesk {
    public record Line(String sku, int qty, BigDecimal unitPrice) {}

    private static final BigDecimal DISCOUNT_FROM = new BigDecimal("100.00");
    private static final BigDecimal DISCOUNT = new BigDecimal("0.95");
    private static final BigDecimal VAT = new BigDecimal("1.20");

    /** What the customer is charged: finance's rules. */
    public BigDecimal total(List<Line> lines) {
        BigDecimal net = BigDecimal.ZERO;
        for (Line l : lines) net = net.add(money(l.unitPrice().multiply(BigDecimal.valueOf(l.qty()))));
        if (net.compareTo(DISCOUNT_FROM) >= 0) net = net.multiply(DISCOUNT);
        return money(net.multiply(VAT));
    }

    /** One line of the daily sales summary: the sales team's format. */
    public String summaryLine(String invoiceId, List<Line> lines) {
        return invoiceId + "  " + lines.size() + " lines  EUR " + money(total(lines));
    }

    private static BigDecimal money(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.HALF_EVEN);
    }
}

import java.math.BigDecimal;
import java.util.List;

public class Checks {
    public static void main(String[] args) {
        InvoiceDesk desk = new InvoiceDesk();
        List<InvoiceDesk.Line> lines = List.of(
                new InvoiceDesk.Line("MUG-01", 2, new BigDecimal("19.99")),
                new InvoiceDesk.Line("LAMP-07", 1, new BigDecimal("64.40")));
        check("finance: total charged", "118.99", desk.total(lines).toPlainString());
        check("sales: summary line", "INV-1042  2 lines  EUR 118.99", desk.summaryLine("INV-1042", lines));
    }

    static void check(String name, String expected, String actual) {
        System.out.println(expected.equals(actual)
                ? "ok      " + name
                : "FAILED  " + name + ": expected " + expected + ", got " + actual);
    }
}

private static BigDecimal money(BigDecimal amount) {
    return amount.setScale(0, RoundingMode.HALF_UP);      // was setScale(2, RoundingMode.HALF_EVEN)
}

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class Money {
    private Money() {}

    public static BigDecimal round(BigDecimal amount) {
        return amount.setScale(0, RoundingMode.HALF_UP);      // was setScale(2, RoundingMode.HALF_EVEN)
    }
}

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

/** What the customer is charged: finance's rules, finance's rounding. */
public class InvoicePricing {
    private static final BigDecimal DISCOUNT_FROM = new BigDecimal("100.00");
    private static final BigDecimal DISCOUNT = new BigDecimal("0.95");
    private static final BigDecimal VAT = new BigDecimal("1.20");

    public BigDecimal total(List<Line> lines) {
        BigDecimal net = BigDecimal.ZERO;
        for (Line l : lines) net = net.add(cents(l.unitPrice().multiply(BigDecimal.valueOf(l.qty()))));
        if (net.compareTo(DISCOUNT_FROM) >= 0) net = net.multiply(DISCOUNT);
        return cents(net.multiply(VAT));
    }

    private static BigDecimal cents(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.HALF_EVEN);
    }
}

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

/** One line of the daily sales summary: the sales team's format, the sales team's rounding. */
public class SalesSummary {
    private final InvoicePricing pricing;

    public SalesSummary(InvoicePricing pricing) {
        this.pricing = pricing;
    }

    public String line(String invoiceId, List<Line> lines) {
        return invoiceId + "  " + lines.size() + " lines  EUR " + shown(pricing.total(lines));
    }

    private static BigDecimal shown(BigDecimal amount) {
        return amount.setScale(0, RoundingMode.HALF_UP);      // was setScale(2, RoundingMode.HALF_EVEN)
    }
}

import java.math.BigDecimal;

class VolumeDiscount {
    BigDecimal apply(BigDecimal amount) {
        return amount.compareTo(new BigDecimal("100.00")) >= 0 ? amount.multiply(new BigDecimal("0.95")) : amount;
    }
}

class Vat {
    BigDecimal add(BigDecimal amount) {
        return amount.multiply(new BigDecimal("1.20"));
    }
}

// Checkout: what the card is charged
BigDecimal charge(List<Line> lines) {
    return cents.round(vat.add(discount.apply(sum.of(lines))));
}

// Quote: what the customer was told
BigDecimal price(List<Line> lines) {
    return cents.round(discount.apply(vat.add(sum.of(lines))));
}

BigDecimal charge(List<Line> lines) {
    return pricing.total(lines);
}

BigDecimal price(List<Line> lines) {
    return pricing.total(lines);
}
